const base = $('Prepare Commercial Evidence Agent Brief').first().json;
const raw = String($json.output || $json.text || $json.choices?.[0]?.message?.content || '');
const parse = (value) => { try { return JSON.parse(value.replace(/^\s*\x60{3}json/i, '').replace(/\x60{3}\s*$/i, '').trim()); } catch { const match = value.match(/\{[\s\S]*\}/); if (!match) return {}; try { return JSON.parse(match[0]); } catch { return {}; } } };
const parsed = parse(raw);
return [{ json: { ...base, agentResult: Object.keys(parsed).length ? parsed : ({ fallback: true, human_review_required: true, confidence: 0 }), agentRaw: raw.slice(0, 24000) } }];

const base = $input.first().json; const exceptions = []; const signals = []; 
const source = base.sourceInput;
const lines = source.items || [];
const unknown = lines.filter(line => !Number.isFinite(line.masterPrice));
const priceDeltas = lines.filter(line => Number.isFinite(line.masterPrice) && Math.abs(line.unitPrice - line.masterPrice) / line.masterPrice > .02);
if (unknown.length) exceptions.push({ code: 'UNKNOWN_ARTICLE', severity: 'stop', owner: 'Stammdaten', detail: 'Mindestens ein Artikel ist nicht freigegeben.', evidence: unknown.map(line => line.sku) });
if (priceDeltas.length) exceptions.push({ code: 'PRICE_DEVIATION', severity: 'review', owner: 'Vertriebsinnendienst', detail: 'Preisabweichung ueber 2 Prozent.', evidence: priceDeltas.map(line => line.sku) });
if (!source.deliveryDate) exceptions.push({ code: 'DELIVERY_DATE_MISSING', severity: 'stop', owner: 'Planung', detail: 'Bestaetigungsfaehiger Liefertermin fehlt.', evidence: [source.document] });
const prepared = { type: 'ERP_ORDER_DRAFT', orderNumber: source.orderNumber, customer: source.customer?.number, lines: lines.map(({ sku, quantity, unitPrice }) => ({ sku, quantity, unitPrice })), deliveryDate: source.deliveryDate, shipTo: source.shipTo, releaseState: 'PENDING_HUMAN_APPROVAL' }; const status = exceptions.some(item => item.severity === 'stop') ? 'STOPPED_FOR_HUMAN_REVIEW' : exceptions.length ? 'HUMAN_REVIEW_REQUIRED' : 'READY_FOR_HUMAN_APPROVAL'; const confidence = Math.max(0, Math.min(1, Number(base.challengeResult?.confidence ?? base.agentResult?.confidence ?? base.visualEvidence?.confidence ?? 0))); return [{ json: { ...base, status, confidence, exceptions, signals, preparedOutput: prepared, humanDecision: { required: true, state: 'pending', owner: "Vertriebsinnendienst" }, externalWritePerformed: false, audit: [...base.audit, { state: 'DETERMINISTIC_GUARDRAILS', status, exceptionCodes: exceptions.map(item => item.code) }] } }];
